-- ====================================================================
-- N-12-2 기존·대안 점수 계산·저장 / N-14 항목별 SHAP 설명 — 피처 사전 FS-DRAFT 시드
-- FastAPI Mock(FP-140)이 돌려주는 SHAP 행을 ASSESSMENT_FACTOR에 저장할 수 있도록
-- DIM_FEATURE에 피처 39개(기존 모델 19 + 대안 데이터 20)를 넣는다 (O-17: 첫 점수 저장 전 FS-DRAFT → FS-V1).
-- 값의 출처: docs/spec/feature_definition.md (피처 정의서 v1.0, FP-132) 11장 "DIM_FEATURE 입력용 표".
--
-- 실행 순서: docs/spec/sql/avenue_ddl.sql 다음에 같은 스키마에서 실행한다.
-- FS-DRAFT 행(FEATURE_SET_VERSION)은 avenue_ddl.sql 기준 데이터에 이미 있다.
--
-- 주의
--  - 정의서가 "임시 결정·수정 가능" 상태라 버전 이름은 FS-DRAFT로 둔다. 정의서가 확정되면 FS-V1로 따로 넣는다.
--  - 정의서 11장이 바뀌면 이 파일도 같이 고친다. 경환 님 더미 DB 생성기가 이 파일을 읽는다(seed/ 폴더).
--  - TODO(FP-132) 표시 이름·SIMULATABLE_YN·표시 순서는 정의서의 B팀 제안값이라 검토가 필요하다(UI 담당·C팀 N-18-8).
--  - 맨 앞 DELETE는 다시 실행할 때 PK 중복을 막기 위한 것이다.
--    FS-DRAFT 코드를 쓰는 ASSESSMENT_FACTOR 행이 생긴 뒤에는 FK 오류가 나므로 실행하지 않는다.
-- ====================================================================
SET DEFINE OFF

DELETE FROM DIM_FEATURE WHERE FEATURE_SET_VERSION = 'FS-DRAFT';

-- 기존 모델·대안 모델 공통 (정의서 3-1·3-5·3-6, 19개)

-- 대안 데이터 5종 (대안 모델에만 쓰임, 화면 [대안] 표시, 정의서 3-2~3-4, 20개)

COMMIT;

-- 확인: TOTAL_CNT 39, ALT_CNT 20, SIM_CNT 9 가 나와야 한다.
SELECT COUNT(*) AS TOTAL_CNT,
       SUM(CASE WHEN ALTERNATIVE_YN = 'Y' THEN 1 ELSE 0 END) AS ALT_CNT,
       SUM(CASE WHEN SIMULATABLE_YN = 'Y' THEN 1 ELSE 0 END) AS SIM_CNT
  FROM DIM_FEATURE
 WHERE FEATURE_SET_VERSION = 'FS-DRAFT';
